@startuml

class Organizer {
  + firstName : string
  + lastName : string
  + email : string
  + postalAddress : string
  + phoneNumber : string
  + password : string
}

class EventType {
  + name : string
}

class Event {
  + occasion : string
  + startDateTime : datetime
  + endDateTime : datetime
}

class Location {
  + name : string
  + address : string
}

class Attendee {
  + firstName : string
  + lastName : string
  + email : string
  + password : string
  + attendanceStatus : string
}

class Task {
  + description : string
  + status : string
}

class TaskAssignment {
}

Attendee "0..*" -- "0..*" Task : selects
Task "0..*" -- "0..1" Attendee : designated for

Organizer "1..*" -- "0..*" Event : organizes
Organizer "0..*" -- "0..*" Event : attends
Event "1" -- "1" EventType
Event "1" -- "1" Location
Event "1" -- "0..*" Task
Event "1" -- "0..*" Attendee : invites

Attendee "0..1" -- "0..*" Event : attends

@enduml

